import{_ as e,o as i,c as o,ak as n}from"./chunks/framework.DyMoXumJ.js";const a="/projects/AIVisionKit/en/latest/assets/1.8Jt0X5h5.webp",r="/projects/AIVisionKit/en/latest/assets/3.BSHU_vGf.webp",p=JSON.parse('{"title":"1. Kit Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1. Kit Introduction.md","filePath":"docs/1. Kit Introduction.md"}'),s={name:"docs/1. Kit Introduction.md"};function l(d,t,c,m,g,u){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="AiBlock" tabindex="-1">1. Kit Introduction <a class="header-anchor" href="#AiBlock" aria-label="Permalink to &quot;1. Kit Introduction{#AiBlock}&quot;">​</a></h1><h2 id="_1-1-kit-overview" tabindex="-1">1.1 Kit Overview <a class="header-anchor" href="#_1-1-kit-overview" aria-label="Permalink to &quot;1.1 Kit Overview&quot;">​</a></h2><p>The AiBlock AI Vision Kit is tailored for elementary STEAM and maker education. Built around an intelligent controller, the kit integrates vision, voice, and line following sensor modules with servos, encoder motors, and structural mechanical components. Paired with graphical programming software and a 16-session progressive curriculum, the kit covers interactive vision, voice control, Mecanum chassis mobility, robotic arm manipulation, and intelligent waste sorting projects. Through hands-on assembly and programming practice, students blend mechanics with artificial intelligence. This systematic approach cultivates algorithmic thinking and collaborative problem-solving from entry-level concepts to comprehensive robotics development, making it well-suited for classrooms, maker clubs, and home learning.</p><img loading="lazy" height="3266" width="4399" src="'+a+'" class="common_img" style="width:1000px;"><h2 id="_1-2-product-features" tabindex="-1">1.2 Product Features <a class="header-anchor" href="#_1-2-product-features" aria-label="Permalink to &quot;1.2 Product Features&quot;">​</a></h2><ol><li><p><strong>Comprehensive AI Hardware Integration</strong>: Equipped with the multifunctional ESP32 block controller, the kit features diverse expansion modules including vision, voice, line following, RGB lighting, dot matrix display, servos, and encoder motors. It covers mainstream AI functions such as color recognition, AprilTag identification, face recognition, number and image classification, voice command interaction, and omnidirectional motion, delivering an all-in-one solution for multidisciplinary smart project development.</p></li><li><p><strong>Versatile Mechanical Construction System</strong>: The kit includes a full structural set for a Mecanum chassis, a 3-DOF robotic arm, and a humanoid robot. It supports multiple model builds such as the Mecanum Off-Roader, Robotic Arm Transporter, and Humanoid Smart Assistant. By integrating mechanical principles such as gear transmission, omnidirectional movement, and multi-joint coordination, the system bridges hands-on assembly with applied physics concepts.</p></li><li><p><strong>Comprehensive Multi-Sensor Fusion Practice</strong>: The system supports collaborative programming across vision, voice, line following, and lighting modules. Hands-on projects incorporate finite state machines, closed-loop tracking, and multi-conditional logic. These structured cases guide students to master multi-device coordinated control, target tracking, automated sorting, and autonomous driving scenarios, reinforcing engineering problem-solving skills.</p></li><li><p><strong>Streamlined and Accessible Hardware Design</strong>: Hardware ports are clearly zoned with silkscreen labels. The Type-C port combines data transmission with power delivery, and modules connect via plug-and-play wiring. Both vision and voice modules feature onboard one-click learning capabilities and come with standardized recognition cards. This setup minimizes wiring complexity and hardware debugging effort in classroom environments.</p></li></ol><h2 id="_1-3-specifications" tabindex="-1">1.3 Specifications <a class="header-anchor" href="#_1-3-specifications" aria-label="Permalink to &quot;1.3 Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;">Brand</td><td style="text-align:left;">Hiwonder</td></tr><tr><td style="text-align:left;">Product model</td><td style="text-align:left;">AiBlock AI Vision Kit</td></tr><tr><td style="text-align:left;">Programming software</td><td style="text-align:left;">WonderLab graphical programming software, Hiwonder Python Editor</td></tr><tr><td style="text-align:left;">Recommended age</td><td style="text-align:left;">8+</td></tr><tr><td style="text-align:left;">Electronic modules</td><td style="text-align:left;">Dot matrix module, RGB light module, WonderLens AI vision module, WonderEcho AI voice module, 6-channel line follower sensor, 180° block servo, 360° long motor</td></tr><tr><td style="text-align:left;">Communication port</td><td style="text-align:left;">Type-C USB port</td></tr><tr><td style="text-align:left;">Building blocks</td><td style="text-align:left;">450+ pieces</td></tr><tr><td style="text-align:left;">Material</td><td style="text-align:left;">ABS</td></tr><tr><td style="text-align:left;">Package weight</td><td style="text-align:left;">1.9 kg</td></tr><tr><td style="text-align:left;">Package dimensions</td><td style="text-align:left;">365 × 270 × 120 mm</td></tr></tbody></table><h2 id="_1-4-packing-list" tabindex="-1">1.4 Packing List <a class="header-anchor" href="#_1-4-packing-list" aria-label="Permalink to &quot;1.4 Packing List&quot;">​</a></h2><img loading="lazy" height="3266" width="4399" src="'+r+'" class="common_img" style="width:1000px;">',10)])])}const f=e(s,[["render",l]]);export{p as __pageData,f as default};
